+        assertEquals("", email.getValue());
+        assertEquals("", phone.getValue());
+        assertEquals("", message.getValue());
+        assertTrue(send.isEnabled());
+    }
+
+    @Test
+    void blankFormFailsValidationWithoutSending() {
+        navigate(ContactView.class);
+
+        Button send = find(Button.class).withText("Send").single();
+        int before = service.getMessages().size();
+
+        test(send).click();
+
+        TextField name = find(TextField.class).withLabel("Name").single();
+        EmailField email = find(EmailField.class).single();
+        TextArea message = find(TextArea.class).single();
+
+        assertTrue(name.isInvalid());
+        assertEquals("Name is required", name.getErrorMessage());
+
+        assertTrue(email.isInvalid());
+        assertEquals("Give an e-mail address or a phone number", email.getErrorMessage());
+
+        assertTrue(message.isInvalid());
+        assertEquals("Message is required", message.getErrorMessage());
+
+        assertEquals(before, service.getMessages().size());
+        assertFalse(find(Notification.class).exists());
+    }
+
+    @Test
+    void invalidEmailIsRejected() {
+        navigate(ContactView.class);
+
+        TextField name = find(TextField.class).withLabel("Name").single();
+        EmailField email = find(EmailField.class).single();
+        TextArea message = find(TextArea.class).single();
+        Button send = find(Button.class).withText("Send").single();
+
+        test(name).setValue("Jane");
+        test(email).setValue("not-an-email");
+        test(message).setValue("Hello");
+
+        test(send).click();
+
+        assertTrue(email.isInvalid());
+        assertEquals("Enter a valid e-mail address", email.getErrorMessage());
+    }
+
+    @Test
+    void tooLongMessageIsRejected() {
+        navigate(ContactView.class);
+
+        TextField name = find(TextField.class).withLabel("Name").single();
+        TextField phone = find(TextField.class).withLabel("Phone").single();
+        TextArea message = find(TextArea.class).single();
+        Button send = find(Button.class).withText("Send").single();
+
+        test(name).setValue("Jane");
+        test(phone).setValue("12345");
+        test(message).setValue("a".repeat(501));
+
+        test(send).click();
+
+        assertTrue(message.isInvalid());
+        assertEquals("Message must be at most 500 characters", message.getErrorMessage());
+    }
+
+    @Test
+    void phoneAloneSatisfiesContactRequirement() {
+        navigate(ContactView.class);
+
+        TextField name = find(TextField.class).withLabel("Name").single();
+        TextField phone = find(TextField.class).withLabel("Phone").single();
+        TextArea message = find(TextArea.class).single();
+        Button send = find(Button.class).withText("Send").single();
+
+        test(name).setValue("Jane");
+        test(phone).setValue("0123456789");
+        test(message).setValue("Hello there");
+
+        test(send).click();
+
+        EmailField email = find(EmailField.class).single();
+        assertFalse(email.isInvalid());
+        assertTrue(find(Notification.class).exists());
+    }
+
+    @Test
+    void validSubmissionSendsClearsAndDisablesSendUntilNextEdit() {
+        navigate(ContactView.class);
+
+        TextField name = find(TextField.class).withLabel("Name").single();
+        EmailField email = find(EmailField.class).single();
+        TextArea message = find(TextArea.class).single();
+        Button send = find(Button.class).withText("Send").single();
+
+        test(name).setValue("Jane Doe");
+        test(email).setValue("jane@example.com");
+        test(message).setValue("Hello there");
+
+        int before = service.getMessages().size();
+        test(send).click();
+
+        Notification notification = find(Notification.class).single();
+        assertTrue(test(notification).getText().contains("Message sent"));
+
+        assertEquals(before + 1, service.getMessages().size());
+        ContactMessage sent = service.getMessages().get(0);
+        assertEquals("Jane Doe", sent.name());
+        assertEquals("Hello there", sent.message());
+
+        assertEquals("", name.getValue());
+        assertEquals("", email.getValue());
+        assertEquals("", message.getValue());
+        assertFalse(send.isEnabled());
+
+        test(name).setValue("New edit");
+        assertTrue(send.isEnabled());
+    }
+
+    @Test
+    void enterKeySendsValidForm() {
+        navigate(ContactView.class);
+
+        TextField name = find(TextField.class).withLabel("Name").single();
+        EmailField email = find(EmailField.class).single();
+        TextArea message = find(TextArea.class).single();
+
+        test(name).setValue("Jane Doe");
+        test(email).setValue("jane@example.com");
+        test(message).setValue("Hello there");
+
+        fireShortcut(Key.ENTER);
+
+        assertTrue(find(Notification.class).exists());
+    }
+
+    @Test
+    void sentMessageAppearsInGridNewestFirst() {
+        navigate(ContactView.class);
+
+        TextField name = find(TextField.class).withLabel("Name").single();
+        EmailField email = find(EmailField.class).single();
+        TextArea message = find(TextArea.class).single();
+        Button send = find(Button.class).withText("Send").single();
+
+        test(name).setValue("First Person");
+        test(email).setValue("first@example.com");
+        test(message).setValue("First message");
