+        com.vaadin.flow.component.grid.Grid<ContactMessage> grid =
+                find(com.vaadin.flow.component.grid.Grid.class).single();
+        ContactMessage first = test(grid).getRow(0);
+        assertEquals("Second Person", first.name());
