+
+        assertTrue(getCurrentView() instanceof AboutView);
+    }
+
+    @Test
+    void leavingWithEmptyFormDoesNotAskAndShowsPersistedMessages() {
+        ContactView view = navigate(ContactView.class);
+        service.add(new ContactMessage("Persisted", "p@example.com", "", "Persisted message",
+                java.time.Instant.now()));
+
+        RouterLink about = find(RouterLink.class).single();
